// Convert the agent's light Markdown into Telegram-safe HTML and split long replies.
const raw = String($input.first().json.output ?? '').trim() || '…';
const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
let t = esc(raw)
  .replace(/^#{1,6}\s+(.+)$/gm, '<b>$1</b>')
  .replace(/\*\*(.+?)\*\*/gs, '<b>$1</b>')
  .replace(/`([^`\n]+)`/g, '<code>$1</code>')
  .replace(/^\s*[-*]\s+/gm, '• ');

const LIMIT = 3900;
const chunks = [];
while (t.length > LIMIT) {
  let cut = t.lastIndexOf('\n\n', LIMIT);
  if (cut < LIMIT / 2) cut = t.lastIndexOf('\n', LIMIT);
  if (cut < LIMIT / 2) cut = LIMIT;
  chunks.push(t.slice(0, cut));
  t = t.slice(cut).trimStart();
}
chunks.push(t);
return chunks.map((text) => ({ json: { text } }));
